// 1. Handle Disable
if (qr_input.enable == 0) {
    qr_state.mode = QR_OFF;
    qr_state.good = 0;
    qr_output.mode = QR_OFF;
    qr_output.good = 0;
    qr_output.worst_residual_rad = 0.0;
    qr_output.q_bi = (adcs_quat_t){1, 0, 0, 0};
    qr_output.used_count = 0;
    qr_output.rejected_outlier = 0;
    return;
}

// 2. Preserve Fault Latch
if (qr_state.mode == QR_FAULT) {
    qr_output.mode = QR_FAULT;
    qr_output.good = 0;
    qr_output.worst_residual_rad = 0.0;
    qr_output.q_bi = (adcs_quat_t){1, 0, 0, 0};
    qr_output.used_count = 0;
    qr_output.rejected_outlier = 0;
    return;
}

// 3. Input Validation
if (qr_input.body == NULL || qr_input.inertial == NULL || qr_input.weights == NULL) {
    qr_state.mode = QR_FAULT;
    qr_output.mode = QR_FAULT;
    qr_output.good = 0;
    qr_output.worst_residual_rad = 0.0;
    qr_output.q_bi = (adcs_quat_t){1, 0, 0, 0};
    qr_output.used_count = 0;
    qr_output.rejected_outlier = 0;
    return;
}
if (qr_input.count < 2 || qr_input.count > 4) {
    qr_state.mode = QR_FAULT;
    qr_output.mode = QR_FAULT;
    qr_output.good = 0;
    qr_output.worst_residual_rad = 0.0;
    qr_output.q_bi = (adcs_quat_t){1, 0, 0, 0};
    qr_output.used_count = 0;
    qr_output.rejected_outlier = 0;
    return;
}
if (!isfinite(qr_config.residual_limit_rad) || 
    qr_config.residual_limit_rad < 0.0 || 
    qr_config.residual_limit_rad > ADCS_PI) {
    qr_state.mode = QR_FAULT;
    qr_output.mode = QR_FAULT;
    qr_output.good = 0;
    qr_output.worst_residual_rad = 0.0;
    qr_output.q_bi = (adcs_quat_t){1, 0, 0, 0};
    qr_output.used_count = 0;
    qr_output.rejected_outlier = 0;
    return;
}
if (qr_config.required_good < 1 || qr_config.required_good > 20) {
    qr_state.mode = QR_FAULT;
    qr_output.mode = QR_FAULT;
    qr_output.good = 0;
    qr_output.worst_residual_rad = 0.0;
    qr_output.q_bi = (adcs_quat_t){1, 0, 0, 0};
    qr_output.used_count = 0;
    qr_output.rejected_outlier = 0;
    return;
}
if (qr_config.allow_outlier_reject != 0 && qr_config.allow_outlier_reject != 1) {
    qr_state.mode = QR_FAULT;
    qr_output.mode = QR_FAULT;
    qr_output.good = 0;
    qr_output.worst_residual_rad = 0.0;
    qr_output.q_bi = (adcs_quat_t){1, 0, 0, 0};
    qr_output.used_count = 0;
    qr_output.rejected_outlier = 0;
    return;
}

// 4. Solve Full Set
const adcs_vec3_t *body_ptr = qr_input.body;
const adcs_vec3_t *inertial_ptr = qr_input.inertial;
const double *weights_ptr = qr_input.weights;
size_t current_count = qr_input.count;
adcs_quat_t q_bi_sol = {1, 0, 0, 0};

adcs_status_t status_full = adcs_quest(body_ptr, inertial_ptr, weights_ptr, current_count, &q_bi_sol);
if (status_full != ADCS_OK) {
    qr_state.mode = QR_FAULT;
    qr_output.mode = QR_FAULT;
    qr_output.good = 0;
    qr_output.worst_residual_rad = 0.0;
    qr_output.q_bi = (adcs_quat_t){1, 0, 0, 0};
    qr_output.used_count = 0;
    qr_output.rejected_outlier = 0;
    return;
}

// 5. Compute Full Residuals
adcs_mat3_t dcm_bi = adcs_quat_to_dcm_bi(&q_bi_sol);
double max_resid_full = -1.0;
size_t idx_max_resid_full = 0;

for (size_t i = 0; i < current_count; i++) {
    adcs_vec3_t body_rotated = adcs_mat3_mul_vec(&dcm_bi, &inertial_ptr[i]);
    double dot = adcs_vec3_dot(&body_rotated, &body_ptr[i]);
    if (dot > 1.0) dot = 1.0;
    if (dot < -1.0) dot = -1.0;
    double angle = acos(dot);
    if (angle > max_resid_full) {
        max_resid_full = angle;
        idx_max_resid_full = i;
    }
}

// 6. Decision Logic
if (max_resid_full <= qr_config.residual_limit_rad) {
    // Full set accepted
    qr_state.mode = QR_MONITOR;
    qr_state.good++;
    if (qr_state.good >= qr_config.required_good) {
        qr_state.mode = QR_READY;
    }

    qr_output.mode = qr_state.mode;
    qr_output.good = qr_state.good;
    qr_output.worst_residual_rad = max_resid_full;
    qr_output.q_bi = q_bi_sol;
    qr_output.used_count = current_count;
    qr_output.rejected_outlier = 0;
    return;
} else {
    // Full set failed limit
    qr_state.good = 0;

    // Try Outlier Rejection
    if (qr_config.allow_outlier_reject == 1 && current_count > 2) {
        adcs_vec3_t reduced_body[4];
        adcs_vec3_t reduced_inertial[4];
        double reduced_weights[4];
        size_t reduced_count = 0;

        for (size_t i = 0; i < current_count; i++) {
            if (i != idx_max_resid_full) {
                reduced_body[reduced_count] = body_ptr[i];
                reduced_inertial[reduced_count] = inertial_ptr[i];
                reduced_weights[reduced_count] = weights_ptr[i];
                reduced_count++;
            }
        }

        adcs_quat_t q_bi_reduced = {1, 0, 0, 0};
        adcs_status_t status_reduced = adcs_quest(reduced_body, reduced_inertial, reduced_weights, reduced_count, &q_bi_reduced);

        if (status_reduced == ADCS_OK) {
            adcs_mat3_t dcm_reduced = adcs_quat_to_dcm_bi(&q_bi_reduced);
            double max_resid_reduced = -1.0;

            for (size_t i = 0; i < reduced_count; i++) {
                adcs_vec3_t body_rotated = adcs_mat3_mul_vec(&dcm_reduced, &reduced_inertial[i]);
                double dot = adcs_vec3_dot(&body_rotated, &reduced_body[i]);
                if (dot > 1.0) dot = 1.0;
                if (dot < -1.0) dot = -1.0;
                double angle = acos(dot);
                if (angle > max_resid_reduced) {
                    max_resid_reduced = angle;
                }
            }

            if (max_resid_reduced <= qr_config.residual_limit_rad) {
                // Reduced set accepted
                qr_state.mode = QR_MONITOR;
                qr_state.good++;
                if (qr_state.good >= qr_config.required_good) {
                    qr_state.mode = QR_READY;
                }

                qr_output.mode = qr_state.mode;
                qr_output.good = qr_state.good;
                qr_output.worst_residual_rad = max_resid_reduced;
                qr_output.q_bi = q_bi_reduced;
                qr_output.used_count = reduced_count;
                qr_output.rejected_outlier = 1;
                return;
            }
        }
    }

    // Fallback to Full Set Result (Monitor)
    qr_output.mode = QR_MONITOR;
    qr_output.good = 0;
    qr_output.worst_residual_rad = max_resid_full;
    qr_output.q_bi = q_bi_sol;
    qr_output.used_count = current_count;
    qr_output.rejected_outlier = 0;
    return;
}

