// 2. Handle Already Fault State
if (qr_state.mode == QR_FAULT) {
    qr_output.mode = QR_FAULT;
    qr_output.good = qr_state.good; // Preserve latch
    // We don't necessarily need to compute residuals if we are just latching, 
    // but let's ensure outputs are consistent. 
